SELECT DISTINCTROW [Gesamt Normierung].Elektrolyseur, [Gesamt Normierung].Datum, [Gesamt Normierung].Zeit, [Gesamt Normierung].[I Gesamt], ([Gesamt Normierung]![I Gesamt]/GetGewFlaeche()) AS i, [Gesamt Normierung].Cc, [Gesamt Normierung].[t An], [Gesamt Normierung].[t Ka], ([Gesamt Normierung]![t An]+[Gesamt Normierung]![t Ka])/2 AS tm, [Gesamt Normierung].Uo, [Gesamt Normierung].Position, [Gesamt Normierung].Ui, Um.[Mittelwert von Ui], [Gesamt Normierung].Un AS Unalt2, TempKorrElement([tm],[Mittelwert von Ui],[Ui]) AS ti, [tm]-([Mittelwert von Ui]-[Ui])*30 AS tiAlt, UnBer([Ui],[i],[ti],[Gesamt Normierung]![Cc]) AS Un, [Gesamt Normierung].Unalt, [Gesamt Normierung].UnVgl3, [Gesamt Normierung].iRef, [Gesamt Normierung].tKorr, [Gesamt Normierung].cKorr
FROM tblGewDaten, [Gesamt Normierung] INNER JOIN Um ON ([Gesamt Normierung].Datum = Um.Datum) AND ([Gesamt Normierung].Elektrolyseur = Um.Elektrolyseur)
WHERE ((([Gesamt Normierung].Elektrolyseur)=(SELECT Bezeichnung FROM tblElektrolyseurbezeichnung WHERE tblGewDaten.IDElektrolyseurUnCeSpcElement = tblElektrolyseurbezeichnung.Nr)) AND (([Gesamt Normierung].Datum)>=[tblGewDaten].[Anfangsdatum] And ([Gesamt Normierung].Datum)<=[tblGewDaten].[Enddatum]) AND (([Gesamt Normierung].Position)=(SELECT IDPositionUnCeSpcElement FROM tblGewDaten)))
ORDER BY [Gesamt Normierung].Elektrolyseur, [Gesamt Normierung].Datum, [Gesamt Normierung].Zeit, [Gesamt Normierung].Position;
